insert into natural_english_private.catalogue(module,senses,questions) values
('advanced-native-1775', '["phrase"]'::jsonb, '{"advanced-native-1775-v1-audio":{"type":"mc","answers":["離座及匆忙告別連到尾班車限制，也顯示她仍想支持妹妹。"],"options":["聽敘述前，說話者已明白路程與告別的關係，沒有新增理解。","離座及匆忙告別連到尾班車限制，也顯示她仍想支持妹妹。","尾班車在演出結束很久後才開，她是因不想聽妹妹而早走。","說話者只覺感動，仍不明白細節怎互相關連。"]},"advanced-native-1775-v2-reply":{"type":"mc","answers":["I could connect the dots emotionally between the journey, the empty seat and her wish to support her sister.","The details became parts of one evening rather than isolated images.","I understood why leaving early had mattered to her.","The account connected the fixed departure time with her wish to remain for the performance."],"options":["I could connect the dots emotionally between the journey, the empty seat and her wish to support her sister.","The details became parts of one evening rather than isolated images.","I understood why leaving early had mattered to her.","The account connected the fixed departure time with her wish to remain for the performance."]},"advanced-native-1775-v1-scene":{"type":"mc","answers":["The records help them connect the dots between the closure and the changed route."],"options":["The records help them connect the dots between the closure and the changed route.","They notice the dates but still treat the route change as unrelated to the closure.","They infer the cause only from the map colours without comparing the records."]},"advanced-native-1775-v1-contrast":{"type":"mc","answers":["只被一句話感動，仍不知道它與其他細節有何關係。"],"options":["把多個細節連起，理解對當事人的意義。","只被一句話感動，仍不知道它與其他細節有何關係。","分清哪些關係有資料支持，哪些仍未明。"]},"advanced-native-1775-v1-branch":{"type":"mc","answers":["Feeling moved is not enough to connect the dots; I still need to see how the journey and goodbye fit together."],"options":["Judge why she left only from my sadness instead of checking the journey she described.","Skip the journey details because only the final feeling matters to understanding the sequence.","Feeling moved is not enough to connect the dots; I still need to see how the journey and goodbye fit together."]},"advanced-native-1775-v1-final":{"type":"open","answers":["Your notes helped me connect the dots emotionally between the sketches and those weekly exchanges with your friend. I am sorry I called them clutter; would you like help keeping them in their original order?","I can now connect the dots between the dates on the drawings and the friendship that supported you that year. I would like to apologise for dismissing them and ask whether you would welcome help organising them your way."],"options":[]}}'::jsonb),
('advanced-native-1776', '["phrase"]'::jsonb, '{"advanced-native-1776-v1-audio":{"type":"mc","answers":["地圖、回憶及記錄提供不同可用學習途徑。"],"options":["地圖、回憶及記錄提供不同可用學習途徑。","目前只可看一張地圖，其他方法仍未提供。","訪客被要求只選商店記錄，不能比較其他資料。","幾種材料被當相同版本，完全沒有各自角度。"]},"advanced-native-1776-v2-reply":{"type":"mc","answers":["They did not have to learn only through one kind of material.","There was more than one door into the past, through maps, memories and shop records.","They could choose a source that matched the question they wanted to ask.","Listening and comparing records were both available starting points."],"options":["They did not have to learn only through one kind of material.","There was more than one door into the past, through maps, memories and shop records.","They could choose a source that matched the question they wanted to ask.","Listening and comparing records were both available starting points."]},"advanced-native-1776-v1-scene":{"type":"mc","answers":["It could offer more than one door into the past, but the additional routes are not available yet."],"options":["It could offer more than one door into the past, but the additional routes are not available yet.","The planned recording and map are already available alongside the film.","The film is being replaced entirely, with no intention of adding another way to learn."]},"advanced-native-1776-v1-contrast":{"type":"mc","answers":["方法較多就表示每項資料都已獲同樣查證。"],"options":["仍可按問題及資料性質選起點再比較。","開始學歷史可用不同資料或方法。","方法較多就表示每項資料都已獲同樣查證。"]},"advanced-native-1776-v1-branch":{"type":"mc","answers":["More than one door into the past gives us choices, but we still need to ask what each source can support."],"options":["I thought the different formats would repeat the same record, so the source would not change what I learned.","More than one door into the past gives us choices, but we still need to ask what each source can support.","I assumed that having three formats meant the staff had already checked the claims against one another."]},"advanced-native-1776-v1-final":{"type":"open","answers":["There is more than one door into the past, so we do not need to use every family source today. Could we start with one remembered meal and then choose a photograph to check who was there?","Your booklet has more than one door into the past through recipes, pictures and spoken memories. I would begin with the meal you most want to ask about, then use another source to test the details."],"options":[]}}'::jsonb),
('advanced-native-1777', '["phrase"]'::jsonb, '{"advanced-native-1777-v1-audio":{"type":"mc","answers":["影片引出問題及查公告的下一步，不被當全部事實。"],"options":["影片已取代公告，說話者不想再查。","說話者只看了公告，沒有因影片產生問題。","每幕情節已被說話者當成可逐一核實的記錄。","影片引出問題及查公告的下一步，不被當全部事實。"]},"advanced-native-1777-v2-reply":{"type":"mc","answers":["I moved from watching the scene to looking for dated records.","The scene started my interest without becoming my only source.","It became a doorway into history by leading me to ask about the closure.","It gave me a question I wanted to investigate in the notices."],"options":["I moved from watching the scene to looking for dated records.","The scene started my interest without becoming my only source.","It became a doorway into history by leading me to ask about the closure.","It gave me a question I wanted to investigate in the notices."]},"advanced-native-1777-v1-scene":{"type":"mc","answers":["It could still be a doorway into history, although the mistaken date needs correction."],"options":["The archive, not the film, is described as the source that first prompted the student’s interest.","The film’s role in starting the research establishes it as a definitive account of the factory.","It could still be a doorway into history, although the mistaken date needs correction."]},"advanced-native-1777-v1-contrast":{"type":"mc","answers":["它已足以取代所有後續查證及背景。"],"options":["可問入口之後需要哪些來源及問題。","一項材料可引出探索過去的興趣。","它已足以取代所有後續查證及背景。"]},"advanced-native-1777-v1-branch":{"type":"mc","answers":["It worked as a doorway into history by helping me notice a question worth checking."],"options":["I took the convincing station scene as confirmation of why the closure happened.","It worked as a doorway into history by helping me notice a question worth checking.","I would only say the film taught me history if I could use it in place of the notices."]},"advanced-native-1777-v1-final":{"type":"open","answers":["A familiar street photograph could be a doorway into history; you do not need to know the whole timeline before joining us. Would you like to bring one question about what has changed, or simply listen the first time?","Your own curiosity can make that photograph a doorway into history, rather than a test you have to pass. We could start with one place you recognise and let the records help us explore it together."],"options":[]}}'::jsonb),
('advanced-native-1778', '["phrase"]'::jsonb, '{"advanced-native-1778-v1-audio":{"type":"mc","answers":["關會堂令一些人失去固定見面及維持友誼的支持。"],"options":["影片主要說活動已改到新固定地方，原有友誼維持方式不受影響。","鄰居早已自行停止每周見面，影片把關閉說成那之後的結果。","關會堂令一些人失去固定見面及維持友誼的支持。","影片只列關閉工程的價錢，沒有人的經歷。"]},"advanced-native-1778-v2-reply":{"type":"mc","answers":["We could see what the loss of the room meant for weekly contact.","Some residents had difficulty keeping connections they had relied on.","The change affected people’s everyday lives, not only the building’s use.","It showed the human cost behind it through the neighbours’ lost meeting place and strained friendships."],"options":["We could see what the loss of the room meant for weekly contact.","Some residents had difficulty keeping connections they had relied on.","The change affected people’s everyday lives, not only the building’s use.","It showed the human cost behind it through the neighbours’ lost meeting place and strained friendships."]},"advanced-native-1778-v1-scene":{"type":"mc","answers":["The figures describe the price, not yet the human cost behind the move."],"options":["The building total itself identifies which relationships the residents lost.","The report has already collected residents’ accounts of changes to their daily lives.","The figures describe the price, not yet the human cost behind the move."]},"advanced-native-1778-v1-contrast":{"type":"mc","answers":["只列建築價目，就當已完整交代當事人經歷。"],"options":["指出某事對人的痛苦或生活負擔。","只列建築價目，就當已完整交代當事人經歷。","先指明 it 是哪件事，再說哪些人怎受影響。"]},"advanced-native-1778-v1-branch":{"type":"mc","answers":["The financial figure does not by itself describe the human cost behind it; the lost contact is another part of the account."],"options":["The financial figure does not by itself describe the human cost behind it; the lost contact is another part of the account.","I thought the saving on the building was the cost you meant, rather than the loss of weekly contact.","I understood the film as an account of the organiser’s workload, rather than changes in the neighbours’ lives."]},"advanced-native-1778-v1-final":{"type":"open","answers":["I am sorry I called the cancellation just one lost evening without understanding the human cost behind it. You had put months into that first performance, and I would like to hear what this loss means to you before suggesting another event.","I spoke too lightly about the cancellation and missed the human cost behind it, including the chance you had worked towards together. Would you like to talk about that, or would quiet company be more welcome for now?"],"options":[]}}'::jsonb),
('advanced-native-1779', '["phrase"]'::jsonb, '{"advanced-native-1779-v1-audio":{"type":"mc","answers":["影片提供主要發展，較細決定可再查信件。"],"options":["信件清單只作片尾答謝，沒有提供較小籌備決定可查。","影片提供主要發展，較細決定可再查信件。","影片主要只讀一封信，沒有社團成立或首展概覽。","所有籌備信件內容已逐段放進影片，無需另查。"]},"advanced-native-1779-v2-reply":{"type":"mc","answers":["The film could not show every stone on the path, so the letters offered access to smaller decisions.","Viewers could explore details the short overview had not included.","The main events were in the film, while the letters contained more of the planning process.","They made it possible to go beyond the selected scenes without treating the film as complete."],"options":["The film could not show every stone on the path, so the letters offered access to smaller decisions.","Viewers could explore details the short overview had not included.","The main events were in the film, while the letters contained more of the planning process.","They made it possible to go beyond the selected scenes without treating the film as complete."]},"advanced-native-1779-v1-scene":{"type":"mc","answers":["The account does not show every stone on the path, so the label should explain its limited coverage."],"options":["The three selected events already amount to every planning decision recorded in the archive.","The account mainly follows each small negotiation and leaves the three major events unexplained.","The account does not show every stone on the path, so the label should explain its limited coverage."]},"advanced-native-1779-v1-contrast":{"type":"mc","answers":["未入短片的事情就必無價值或不曾發生。"],"options":["未入短片的事情就必無價值或不曾發生。","可交代選材範圍並指向其他記錄。","作品不會含發展中的每項細節。"]},"advanced-native-1779-v1-branch":{"type":"mc","answers":["A short film cannot show every stone on the path; omission alone does not decide the letter’s value."],"options":["A short film cannot show every stone on the path; omission alone does not decide the letter’s value.","I assumed the letter was left out because another source had already covered the same details.","I took the archive listing as a summary of the letter, so I thought we already knew what it added."]},"advanced-native-1779-v1-final":{"type":"open","answers":["We cannot show every stone on the path in a short history, but this date changes the explanation of the opening. Could we restore the checked sequence rather than describe the room as a response to a flood that came later?","Not showing every stone on the path is reasonable, yet the opening-before-the-flood point is necessary for an accurate account. I would correct that one line without trying to include every planning letter."],"options":[]}}'::jsonb),
('advanced-native-1780', '["phrase"]'::jsonb, '{"advanced-native-1780-v1-audio":{"type":"mc","answers":["節目交代主要發展結構，較細材料仍可另讀。"],"options":["節目主要逐封分析兩信，沒有交代提案到協議的大方向。","節目只給最後協議，沒有提案到修改的發展。","節目只比較目前場地，沒有交代會堂辯論的早前階段。","節目交代主要發展結構，較細材料仍可另讀。"]},"advanced-native-1780-v2-reply":{"type":"mc","answers":["It gave the structure before I read the individual letters.","The main sequence was clearer, while the finer discussions remained for later.","It showed the shape of the mountain through the main stages of the hall debate.","I could see how the first proposal led to a revised agreement."],"options":["It gave the structure before I read the individual letters.","The main sequence was clearer, while the finer discussions remained for later.","It showed the shape of the mountain through the main stages of the hall debate.","I could see how the first proposal led to a revised agreement."]},"advanced-native-1780-v1-scene":{"type":"mc","answers":["He knows the detail of one episode, but the shape of the mountain is not yet clear to him."],"options":["He only needs to repeat the letters more accurately, without checking how the main stages fit together.","He knows the detail of one episode, but the shape of the mountain is not yet clear to him.","Knowing that negotiation already gives him the outline of the school’s whole development."]},"advanced-native-1780-v1-contrast":{"type":"mc","answers":["每項細節及原因都已同樣掌握。"],"options":["仍可由輪廓挑下一步要查的部分。","已看較大的結構或主要階段。","每項細節及原因都已同樣掌握。"]},"advanced-native-1780-v1-branch":{"type":"mc","answers":["I have the shape of the mountain, but the budget discussion may still explain why this particular change was made."],"options":["I have the shape of the mountain, but the budget discussion may still explain why this particular change was made.","The programme follows the proposal through to agreement, so I assumed it had also settled the budget reasons behind the revision.","I thought the budget discussion concerned a different proposal, so I would stay with the overview before checking it."]},"advanced-native-1780-v1-final":{"type":"open","answers":["I can see the shape of the mountain from the overview, but I have not checked the letters about the first shared performance. Could I narrow the question to that turning point before giving you a realistic plan for the report?","The overview has given me the shape of the mountain, rather than the evidence for every stage. I would like to identify which letters I need for the first joint concert before promising a finished account."],"options":[]}}'::jsonb),
('advanced-native-1782', '["phrase"]'::jsonb, '{"advanced-native-1782-v1-audio":{"type":"mc","answers":["影集引興趣，引用具體話語前仍查原來源。"],"options":["原敘述在看影集前就已引用，今次沒有因那幕再查。","影集引興趣，引用具體話語前仍查原來源。","影集對白被直接當學徒留下的原話，沒有核。","影集沒有引出任何問題，說話者拒看其他資料。"]},"advanced-native-1782-v2-reply":{"type":"mc","answers":["I treated the series as a gateway rather than a final authority on the apprentice’s words.","An engaging scene was not enough to establish the exact quotation.","I wanted to distinguish the dramatisation from what the source actually recorded.","The scene gave me a question, while the original account could help check it."],"options":["I treated the series as a gateway rather than a final authority on the apprentice’s words.","An engaging scene was not enough to establish the exact quotation.","I wanted to distinguish the dramatisation from what the source actually recorded.","The scene gave me a question, while the original account could help check it."]},"advanced-native-1782-v1-scene":{"type":"mc","answers":["We can use it as a gateway rather than a final authority, while correcting the date and checking specific claims."],"options":["The series should be assessed only as a final reference, without considering the questions it prompted.","The dramatised caption is stronger evidence for the date because the series inspired the research.","We can use it as a gateway rather than a final authority, while correcting the date and checking specific claims."]},"advanced-native-1782-v1-contrast":{"type":"mc","answers":["把戲劇對白直接引成未查過的歷史原話。"],"options":["把戲劇對白直接引成未查過的歷史原話。","保留作品的啟發，也指出哪些部分待證。","用作品引問題，再找原資料核具體聲稱。"]},"advanced-native-1782-v1-branch":{"type":"mc","answers":["Let us use it as a gateway rather than a final authority and check which words the original record actually preserves."],"options":["I thought the subtitles were taken directly from the records, so I would quote that line as it stands.","I understood the actor’s careful delivery as confirmation that these were the apprentice’s recorded words.","Let us use it as a gateway rather than a final authority and check which words the original record actually preserves."]},"advanced-native-1782-v1-final":{"type":"open","answers":["Could you describe my introduction as a gateway rather than a final authority on the move? I have linked the two sources I checked and marked the question that remains open, so readers can see what the article does and does not establish.","I meant the article to be a gateway rather than a final authority, not a claim that every reason has been found. Please revise that description and keep the source links beside the open question."],"options":[]}}'::jsonb),
('advanced-native-1783', '["phrase"]'::jsonb, '{"advanced-native-1783-v1-audio":{"type":"mc","answers":["訪談補參與者受時間影響的角度，不只聚會時段。"],"options":["訪談只核房間號碼，沒有談時間對人的影響。","從別區來的成員表示關門時間沒有影響能否出席。","訪談補參與者受時間影響的角度，不只聚會時段。","關門時間是從訪談才得知，借房記錄主要記人們路程。"]},"advanced-native-1783-v2-reply":{"type":"mc","answers":["We learned what the timetable meant for people’s ability to attend.","The records gained a connection with members’ journeys.","The interviews explained a consequence that the booking times alone did not show.","They gave us a fuller picture of how the closing time affected members from farther away."],"options":["We learned what the timetable meant for people’s ability to attend.","The records gained a connection with members’ journeys.","The interviews explained a consequence that the booking times alone did not show.","They gave us a fuller picture of how the closing time affected members from farther away."]},"advanced-native-1783-v1-scene":{"type":"mc","answers":["The interviews offer a fuller picture, while the timing and competing explanations still need checking."],"options":["The transport accounts already give a checked date and confirmed cause, rather than a possibility still being investigated.","The new accounts only repeat the same lack-of-interest explanation without adding another possibility.","The interviews offer a fuller picture, while the timing and competing explanations still need checking."]},"advanced-native-1783-v1-contrast":{"type":"mc","answers":["現在已是完整終局，後續資料不可能改理解。"],"options":["理解比之前加入較多相關面向。","現在已是完整終局，後續資料不可能改理解。","仍可標未知及待核的關係。"]},"advanced-native-1783-v1-branch":{"type":"mc","answers":["We have a fuller picture, but we still need to check whether the travel disruption matches the date of the cancellation."],"options":["Two passengers mentioned the disruption, so I thought that settled when it happened.","I thought the first interview was enough to explain the cancellation, before comparing it with the transport accounts.","We have a fuller picture, but we still need to check whether the travel disruption matches the date of the cancellation."]},"advanced-native-1783-v1-final":{"type":"open","answers":["I can offer my own experience, but a fuller picture would need voices from people who could not attend regularly too. If you would like, I can ask whether anyone would welcome an introduction before sharing their contact details.","My paragraph is one perspective rather than the fuller picture of the whole class. I would be glad to contribute it, while helping you invite other willing participants without speaking for them."],"options":[]}}'::jsonb),
('advanced-native-1784', '["phrase"]'::jsonb, '{"advanced-native-1784-v1-audio":{"type":"mc","answers":["聲音、照片及日常次序，讓物件連人的活動。"],"options":["檔案只按編號列工具，沒有人的聲音或活動。","錄下的工人說明被當成只有工具編號，沒有工作次序。","訪客只看目前工作規定，沒有接觸早前記錄。","聲音、照片及日常次序，讓物件連人的活動。"]},"advanced-native-1784-v2-reply":{"type":"mc","answers":["Visitors could follow work being done instead of only reading names.","The photographs and voice helped turn the catalogue into an experience of use.","It breathed life into the past by connecting the tools with the worker’s morning.","The recorded instructions showed how the objects belonged to an ordinary routine."],"options":["Visitors could follow work being done instead of only reading names.","The photographs and voice helped turn the catalogue into an experience of use.","It breathed life into the past by connecting the tools with the worker’s morning.","The recorded instructions showed how the objects belonged to an ordinary routine."]},"advanced-native-1784-v1-scene":{"type":"mc","answers":["The upload alone does not show that they have breathed life into the past; how people can engage with it still matters."],"options":["The page count is a better measure of visitor understanding than watching how people follow the records.","Visitors are already listening to the workers and following explained daily routines.","The upload alone does not show that they have breathed life into the past; how people can engage with it still matters."]},"advanced-native-1784-v1-contrast":{"type":"mc","answers":["場景有感染力就證每項新增細節都是史實。"],"options":["呈現讓過去較生動可感。","場景有感染力就證每項新增細節都是史實。","可核記錄、說清重構並觀察觀眾怎理解。"]},"advanced-native-1784-v1-branch":{"type":"mc","answers":["To breathe life into the past, we should test how visitors follow the records, not only count the uploaded pages."],"options":["To breathe life into the past, we should test how visitors follow the records, not only count the uploaded pages.","I thought making the scans legible meant visitors would already find the history vivid without any explanation.","I would first maximise the collection and choose a story for visitors after all the scanning is finished."]},"advanced-native-1784-v1-final":{"type":"open","answers":["The scene did breathe life into the past, but we need to label the line we created rather than let it pass as a quotation. Could we keep the useful demonstration while making that distinction clear before the next performance?","Our demonstration helped breathe life into the past by showing the tools in use. I would keep it and add a clear note about the reconstructed dialogue, so the audience can separate it from the worker’s recorded words."],"options":[]}}'::jsonb),
('advanced-native-1786', '["phrase"]'::jsonb, '{"advanced-native-1786-v1-audio":{"type":"mc","answers":["論壇有珍貴原圖，也有需核圖說的轉貼。"],"options":["小組主要在比排版，沒把圖說是否改過當問題。","論壇有珍貴原圖，也有需核圖說的轉貼。","論壇只存同一份已核圖說，沒有不同版本。","轉貼位置比原圖近，就足以決定正確日期。"]},"advanced-native-1786-v2-reply":{"type":"mc","answers":["The forum was a gold mine, but it could also be a minefield because reposted captions had changed.","Useful originals were mixed with versions whose captions needed checking.","A picture’s appearance in the forum did not establish the wording of its original label.","The group wanted the value of the images without confusing later captions with early records."],"options":["The forum was a gold mine, but it could also be a minefield because reposted captions had changed.","Useful originals were mixed with versions whose captions needed checking.","A picture’s appearance in the forum did not establish the wording of its original label.","The group wanted the value of the images without confusing later captions with early records."]},"advanced-native-1786-v1-scene":{"type":"mc","answers":["It is a gold mine, but it can also be a minefield; we can use the original diary while checking the retellings."],"options":["Copy the retelling’s date before comparing it with the dated diary.","It is a gold mine, but it can also be a minefield; we can use the original diary while checking the retellings.","Leave the diary unread and base the account only on the short retelling because it is easier to use."]},"advanced-native-1786-v1-contrast":{"type":"mc","answers":["只因資料很多，就直接把未查圖說當原記錄。"],"options":["指出具體風險而不把整庫一概判無用。","利用有來源資料，也核轉貼的差異。","只因資料很多，就直接把未查圖說當原記錄。"]},"advanced-native-1786-v1-branch":{"type":"mc","answers":["It is a gold mine, but it can also be a minefield; repeated captions still need comparison with the original."],"options":["I would trust the local fan page’s caption first, because its followers know the place, even though I have not compared the versions.","It is a gold mine, but it can also be a minefield; repeated captions still need comparison with the original.","I assumed the people who reposted the caption had already checked its date."]},"advanced-native-1786-v1-final":{"type":"open","answers":["The forum is a gold mine, but it can also be a minefield, and I relied on a reposted date too quickly. I have corrected my post and linked the original caption so others can check the difference.","This collection is a gold mine, but it can also be a minefield when later captions look like original records. I am sorry for the wrong date in my post; the corrected version now points to the dated image itself."],"options":[]}}'::jsonb),
