('advanced-native-1799', '["phrase"]'::jsonb, '{"advanced-native-1799-v1-audio":{"type":"mc","answers":["說話者較能分清問題，答案仍待查。"],"options":["說話者只心情較愉快，仍完全分不開兩問題。","說話者已查到兩問題答案，安靜一晚只改了寫法。","兩問題本來一直分明，沒有之前混亂。","說話者較能分清問題，答案仍待查。"]},"advanced-native-1799-v2-reply":{"type":"mc","answers":["The thinking was clearer, though the answers still needed evidence.","I became better able to organise the uncertainty rather than claim it had all been resolved.","It helped clear the mental fog, and I could separate the two questions.","I could see what I needed to ask instead of mixing the notes together."],"options":["The thinking was clearer, though the answers still needed evidence.","I became better able to organise the uncertainty rather than claim it had all been resolved.","It helped clear the mental fog, and I could separate the two questions.","I could see what I needed to ask instead of mixing the notes together."]},"advanced-native-1799-v1-scene":{"type":"mc","answers":["Feeling happier does not yet show that the clip helped clear the mental fog about the arrangements."],"options":["She has already separated the two plans and checked which one she agreed to.","Feeling happier does not yet show that the clip helped clear the mental fog about the arrangements.","The smile is enough to establish that she can now explain the two arrangements clearly."]},"advanced-native-1799-v1-contrast":{"type":"mc","answers":["既清醒些，之前每個猜想便自動正確。"],"options":["仍需核資料，不能用清晰感替答案背書。","當事人感到較能清晰組織思考。","既清醒些，之前每個猜想便自動正確。"]},"advanced-native-1799-v1-branch":{"type":"mc","answers":["The evening helped clear the mental fog, but it did not check the letter’s date for me."],"options":["Now the questions feel clearer, I trust my earlier guess about the date more.","I thought mental fog referred only to mood, so separating the questions would not show a change in my thinking.","The evening helped clear the mental fog, but it did not check the letter’s date for me."]},"advanced-native-1799-v1-final":{"type":"op